import{z as l,x as o,o as r,c as d,q as B,j as i,D as e,d as t,s as n,S as A,b as E}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"传输门与三态","description":"","frontmatter":{"title":"传输门与三态","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/transmission-tristate.md","filePath":"cs/transmission-tristate.md","lastUpdated":1791063341000}'),p={name:"cs/transmission-tristate.md"};function m(D,a,h,C,c,u){const s=o("Mermaid");return r(),d("div",null,[a[2]||(a[2]=B('<h1 id="传输门与三态" tabindex="-1">传输门与三态 <a class="header-anchor" href="#传输门与三态" aria-label="Permalink to &quot;传输门与三态&quot;">​</a></h1><div class="epigraph"><p>互补 CMOS 门总要把输出钉在轨上；传输门把通路打开或切断，三态则允许把线让给别人驱。</p><footer>—— 据 Harris and Harris, Digital Design and Computer Architecture 整理</footer></div><p>上一课<a href="/cs/nand-universal">与或非与万能门</a>钉死了 NAND/NOR 能拼任意布尔函数。本课不重证完备，也不从模拟开关电阻另起。缺口是：后课总线、寄存器旁路、多路选择，经常需要<strong>不驱动</strong>某根线，而不是再做一个总在推 0/1 的门。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>静态 CMOS 输出在稳态靠近电源或地，两块若接到同一节点会对打。缺口是两种受控连接：传输门（nMOS+pMOS 并联，栅相反）导通时近似双向通路；三态缓冲在使能无效时输出高阻 \\(Z\\)，使能有效时等同普通缓冲。多驱动线必须互斥使能，否则争用。</p><p><span class="marginnote">术语翻译：高阻（Z）就是「这根线我现在不管了」——输出级断开，既不推 0 也不推 1，线上电压由电容记忆或由别的驱动者说了算。它不是 0 和 1 之外的第三种电平。</span></p><p>本课只钉通路与高阻。延迟、负载计入<a href="/cs/gate-delay">下一课</a>。MUX 可用传输树或门级，后课再命名。</p><h3 id="高阻不是「第三种逻辑-1」" tabindex="-1">高阻不是「第三种逻辑 1」 <a class="header-anchor" href="#高阻不是「第三种逻辑-1」" aria-label="Permalink to &quot;高阻不是「第三种逻辑 1」&quot;">​</a></h3><p>\\(Z\\) 表示没人推，线上电压由电容保持或被别人驱，不是合法数字值。把三态当 ternary 逻辑，后课总线会把浮空当数据。传输门导通时两端都应是强 0/1，弱电平经传输管会再衰减。</p><p><span class="marginnote">Harris 用传输门做小型 MUX，用三态做总线。本课不把动态逻辑、多米诺当主干。双向引脚是三态的封装形态，协议仍是互斥驱动。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>传输门：两管互补开启，通过强 0 与强 1。三态：使能与数据经与非/或非再接到互补输出级，或输出级本身可关断。总线：若干三态接同一节点，译码保证同一时刻至多一个有效。</p><p><span class="marginnote">直觉类比：三态总线像圆桌会议——同一时刻只有拿到话筒（使能）的人能发言，其余人闭嘴（高阻）；两人同时开口就是争用，听到的全是噪音，硬件还会发热。</span></p>',13)),(r(),i(A,null,{default:e(()=>[n(s,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20NAND%5B%22%E9%9D%99%E6%80%81%20CMOS%20%E9%97%A8%22%5D%20--%3E%20TG%5B%22%E4%BC%A0%E8%BE%93%E9%97%A8%EF%BC%9A%E5%8F%97%E6%8E%A7%E9%80%9A%E8%B7%AF%22%5D%0A%20%20NAND%20--%3E%20TS%5B%22%E4%B8%89%E6%80%81%EF%BC%9A%E5%8F%AF%E9%AB%98%E9%98%BB%22%5D%0A%20%20TS%20--%3E%20BUS%5B%22%E4%BA%92%E6%96%A5%E9%A9%B1%E5%8A%A8%E7%9A%84%E7%BA%BF%22%5D%0A%20%20BUS%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E9%97%A8%E6%97%B6%E5%BB%B6%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[t("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"有了高阻，组合连接不再只是门输出对门输入：还可以把多块的输出接到同一点再选通。后课寄存器堆读口、外设总线都靠这层。功能上仍可用 NAND 网模拟 MUX，面积与走线不同。传输门本身几乎不恢复电平，长链要插反相器——这是延迟课的负载，本课只承认。",-1)),a[5]||(a[5]=E("p",null,[E("span",{class:"marginnote"},"常见误区：以为「不驱动」等于输出 0。高阻时线上电压悬着，读到的可能是上一次留下的旧电平；把浮空当数据用，是真实硬件里最难查的一类 bug。")],-1)),(r(),i(A,null,{default:e(()=>[n(s,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20EN%5B%22%E8%AF%91%E7%A0%81%E5%99%A8%EF%BC%9A%E5%90%8C%E4%B8%80%E6%97%B6%E5%88%BB%3Cbr%2F%3E%E8%87%B3%E5%A4%9A%E6%94%BE%E8%A1%8C%E4%B8%80%E4%B8%AA%E4%BD%BF%E8%83%BD%22%5D%20--%3E%20E1%5B%22%E5%99%A8%E4%BB%B6%20A%EF%BC%9A%E4%BD%BF%E8%83%BD%E6%9C%89%E6%95%88%22%5D%0A%20%20EN%20--%3E%20E2%5B%22%E5%99%A8%E4%BB%B6%20B%EF%BC%9A%E4%BD%BF%E8%83%BD%E6%97%A0%E6%95%88%22%5D%0A%20%20E1%20--%3E%20OUT%5B%22%E5%99%A8%E4%BB%B6%20A%20%E9%A9%B1%E5%8A%A8%E6%80%BB%E7%BA%BF%22%5D%0A%20%20E2%20-.-%3E%7C%22%E8%BE%93%E5%87%BA%E9%AB%98%E9%98%BB%EF%BC%8C%E4%B8%8D%E9%A9%B1%E5%8A%A8%22%7C%20OUT%0A%20%20BAD%5B%22%E9%94%99%E8%AF%AF%EF%BC%9A%E4%B8%A4%E4%B8%AA%E4%BD%BF%E8%83%BD%E5%90%8C%E6%97%B6%E6%9C%89%E6%95%88%22%5D%20--%3E%20FIGHT%5B%22%E4%B8%A4%E8%BE%93%E5%87%BA%E5%AF%B9%E6%89%93%3Cbr%2F%3E%E5%A4%A7%E7%94%B5%E6%B5%81%EF%BC%8C%E7%94%B5%E5%B9%B3%E4%B8%8D%E5%AE%9A%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=B('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 I/O 标准电压、漏极开路与上拉电阻的模拟细节（承认开漏是另一种「线与」）。不引入模拟乘法器式的传输特性。</p><p>后课默认：组合块除了推轨，还可以切断；总线必须互斥。任意组合功能至此都能落成门网或传输/三态网；时延下一课才量化。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>传输门是受控双向通路；三态输出可高阻。</li><li>同一节点多驱动必须互斥，否则争用。</li><li>\\(Z\\) 不是第三种逻辑值。</li><li>出处：Harris and Harris。</li></ul>',5))])}const T=l(p,[["render",m]]);export{f as __pageData,T as default};
